const user = { name: 'Ada', items: 3 };

function Greeting() {
  return (
    <p>
      {user.name} has {user.items} {user.items === 1 ? 'item' : 'items'} in the cart.
      Total: {(19.99 * user.items).toFixed(2)}
    </p>
  );
}

function Badge({ count }) {
  return (
    <>
      <span className="badge" style={{ backgroundColor: 'navy', color: 'white' }}>
        {count} new
      </span>
      <label htmlFor="email">Email</label>
      <input id="email" type="email" disabled={count === 0} />
    </>
  );
}

function Status({ user }) {
  if (!user) return null;

  return (
    <div>
      {user.online ? <span>Online</span> : <span>Offline</span>}
      {user.unread > 0 && <strong>{user.unread} unread</strong>}
    </div>
  );
}
